#!/usr/bin/env node

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { bundleBrowserEntry } from '../../artifact/scripts/generate-artifact-shell.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export const DESIGN_STUDIO_BUNDLE_BANNER =
  '// generated by packages/design/scripts/generate-design-studio.mjs';

/**
 * Raw and gzip byte ceilings per generated asset, asserted by the package tests.
 * Raise one deliberately, keeping about 20% headroom over the measured size.
 */
export const DESIGN_STUDIO_ASSET_BUDGETS = Object.freeze({
  'templates/studio/studio.js': Object.freeze({ bytes: 267_264, gzipBytes: 61_440 }),
});

export class DesignStudioGenerationError extends Error {
  constructor(code, message, details = {}) {
    super(message);
    this.name = 'DesignStudioGenerationError';
    this.code = code;
    this.details = details;
  }
}

/** Bundle the studio, review experience and Handoff Center into one classic script. */
export function renderDesignStudioRuntimeAsset({ projectRoot = root } = {}) {
  return bundleBrowserEntry('lib/design/ui/studio-runtime.mjs', {
    projectRoot,
    banner: DESIGN_STUDIO_BUNDLE_BANNER,
  });
}

/** Render every generated design studio asset, keyed by package-relative path. */
export function renderDesignStudioAssets({ projectRoot = root } = {}) {
  return { 'templates/studio/studio.js': renderDesignStudioRuntimeAsset({ projectRoot }) };
}

function staleTargets(projectRoot, assets) {
  return Object.entries(assets)
    .filter(([target, bytes]) => {
      const path = resolve(projectRoot, target);
      return !existsSync(path) || readFileSync(path, 'utf8') !== bytes;
    })
    .map(([target]) => target)
    .sort();
}

export function runDesignStudioGenerator({
  argv = process.argv.slice(2),
  projectRoot = root,
} = {}) {
  const unsupported = argv.filter((arg) => arg !== '--check');
  if (unsupported.length > 0) {
    throw new DesignStudioGenerationError(
      'E_DESIGN_STUDIO_GENERATOR_ARGUMENT',
      `Unsupported argument${unsupported.length === 1 ? '' : 's'}: ${unsupported.join(', ')}`,
      { unsupported },
    );
  }
  const assets = renderDesignStudioAssets({ projectRoot });
  const stale = staleTargets(projectRoot, assets);
  if (argv.includes('--check')) {
    if (stale.length > 0) {
      throw new DesignStudioGenerationError(
        'E_DESIGN_STUDIO_DRIFT',
        `Generated design studio assets are stale:\n${stale.map((target) => `  - ${target}`).join('\n')}\nRun: npm run generate`,
        { staleTargets: stale },
      );
    }
    return { ok: true, mode: 'check', staleTargets: [] };
  }
  for (const target of stale) {
    const path = resolve(projectRoot, target);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, assets[target], 'utf8');
  }
  return { ok: true, mode: 'write', written: stale };
}

function main() {
  try {
    const result = runDesignStudioGenerator();
    if (result.mode === 'check') {
      process.stdout.write('Design studio assets are current.\n');
    } else if (result.written.length === 0) {
      process.stdout.write('Design studio assets already current.\n');
    } else {
      process.stdout.write(
        `Generated design studio assets:\n${result.written.map((target) => `  - ${target}`).join('\n')}\n`,
      );
    }
  } catch (error) {
    process.stderr.write(`${error?.code ?? 'E_DESIGN_STUDIO_GENERATION'}: ${error.message}\n`);
    process.exitCode = 1;
  }
}

if (resolve(process.argv[1] ?? '') === fileURLToPath(import.meta.url)) main();
